def make(n):
    # Build: (a or (b or (c or ...))) using dummy comparisons
    parts = []
    for i in range(n):
        parts.append(f"python_version == '{i}'")
    # join with ' or ' and wrap each level in parentheses
    expr = parts[0]
    for p in parts[1:]:
        expr = f"({expr} or {p})"
    return [[expr]]

def make(n):
    # Build a marker with n nested 'or' groups: a or (b or (c ...))
    parts = []
    for i in range(n):
        parts.append(f"python_version == '3.{i % 10}'")
    # join with ' or ' and wrap each level in parentheses
    expr = parts[0]
    for p in parts[1:]:
        expr = f"({expr} or {p})"
    return [[expr]]
